 tn_sql('START TRANSACTION');try{foreach(array('ina_comment','ina_scores','ina_at_scores')as$table){tn_sql('DELETE FROM fixture_'.$table);}tn_sql("INSERT INTO fixture_ina_data(config_name,config_value) VALUES('games_comments','1'),('games_comment_size','256'),('games_pm_comment','1')");tn_sql("UPDATE fixture_ina_cat SET mod_id=10 WHERE cat_id=3");tn_sql("INSERT INTO fixture_ina_comment(comment_id,comment_game_name,comment_user_id,comment_username,comment_user_ip,comment_time,comment_text) VALUES(42,'synthetic-rating',9,'Recipient','7f000002',1,'Original &amp; Grüße 😀'),(43,'second-game',10,'Second','7f000003',2,'Other game')");tn_sql("INSERT INTO fixture_ina_scores(game_name,player_id,score,date) VALUES('synthetic-rating',7,20,".time().')');tn_sql('COMMIT');}catch(Exception$e){tn_sql('ROLLBACK');throw$e;}
