}
function cmt_call($action='view',$id=42,$game=1,$raw='Changed Grüße 😀')
{
 try{return array('ok'=>true,'value'=>$action==='view'?phpbb_arcade_comment_view($GLOBALS['db'],$GLOBALS['userdata'],$game,$id):phpbb_arcade_comment_change($GLOBALS['db'],$GLOBALS['userdata'],$action,$game,$action==='add'?0:$id,$raw,htmlspecialchars($raw,ENT_QUOTES,'UTF-8')),'error'=>'');}catch(PhpbbArcadeRatingFailure$e){return array('ok'=>false,'value'=>null,'error'=>$e->getMessage());}
}
function cmt_controller($post=array(),$get=array('game_id'=>'1'),$method='GET')
{
 global $db,$userdata,$lang,$phpEx,$phpbb_root_path,$board_config,$template,$HTTP_POST_VARS,$HTTP_GET_VARS,$arcade,$images;
 $HTTP_POST_VARS=$_POST=$post;$HTTP_GET_VARS=$_GET=$get;$_SERVER['REQUEST_METHOD']=$method;$images=array('icon_edit'=>'edit.png','icon_delpost'=>'delete.png');$phpbb_root_path=$GLOBALS['tn_app'];$template=nt_template('arcade_comment_body.tpl');
 $s=file_get_contents($phpbb_root_path.'arcade_comment.php');$a=strpos($s,"require_once(\$phpbb_root_path . 'includes/functions_arcade_comment_storage.'");nt_check($a!==false,'Full actual comment request/controller body');$code=preg_replace('/\?>\s*$/D','',substr($s,$a));
 foreach(array('page_header','page_tail')as$part){$needle="include(\$phpbb_root_path . 'includes/$part.'.\$phpEx);";nt_check(strpos($code,$needle)!==false,'Only unrelated global layout replaced');$code=str_replace($needle,'/* unrelated layout sink */',$code);}
 // Real controller terminal exits are a controlled response sink in tests.
 $code=preg_replace('/\bexit;/', 'throw new \\CmtUiExit(-1, "");',$code);
 $message='';$level=null;ob_start();try{eval('namespace CmtUiSink; use \\Exception; use \\Error;'.$code);}catch(CmtUiExit$e){$message=$e->getMessage();$level=$e->level;}catch(NewsReaderFailure$e){$message=$e->getMessage();$level=GENERAL_ERROR;}finally{$html=ob_get_contents();ob_end_clean();}
 return array('html'=>$html,'message'=>$message,'level'=>$level);
}
function cmt_transition($kind)
{
 if($kind==='disabled'){tn_sql("UPDATE fixture_ina_data SET config_value='0' WHERE config_name='games_comments'");}
 elseif($kind==='demoted'){tn_sql('UPDATE fixture_users SET user_level=0 WHERE user_id=7');}
 elseif($kind==='mod-revoked'){tn_sql('UPDATE fixture_ina_cat SET mod_id=10 WHERE cat_id=3');}
 elseif($kind==='owner-changed'){tn_sql('UPDATE fixture_ina_comment SET comment_user_id=9 WHERE comment_id=42');}
 elseif($kind==='no-score'){tn_sql('DELETE FROM fixture_ina_scores');}
 elseif($kind==='old-score'){tn_sql('UPDATE fixture_ina_scores SET date='.(time()-3601));}
 elseif($kind==='future-score'){tn_sql('UPDATE fixture_ina_scores SET date='.(time()+3600));}
 else{rtg_change($kind);}
}
